CREATE TABLE inbound_identity_aliases(instance_id INTEGER NOT NULL REFERENCES instances(id),source_locator TEXT NOT NULL,tag TEXT NOT NULL,protocol TEXT NOT NULL,inbound_id TEXT NOT NULL REFERENCES catalog_inbounds(id),first_seen_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,PRIMARY KEY(instance_id,source_locator,tag,protocol));
INSERT INTO inbound_identity_aliases SELECT instance_id,source_ref,tag,protocol,id,discovered_at,discovered_at FROM catalog_inbounds;
CREATE TABLE inbound_identity_history(id INTEGER PRIMARY KEY,inbound_id TEXT NOT NULL REFERENCES catalog_inbounds(id),instance_id INTEGER NOT NULL REFERENCES instances(id),old_tag TEXT NOT NULL,new_tag TEXT NOT NULL,old_source TEXT NOT NULL,new_source TEXT NOT NULL,config_hash TEXT NOT NULL,method TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE inbound_identity_pending(id TEXT PRIMARY KEY,instance_id INTEGER NOT NULL REFERENCES instances(id),source_locator TEXT NOT NULL,tag TEXT NOT NULL,protocol TEXT NOT NULL,profile_json TEXT NOT NULL,listen_address TEXT NOT NULL,candidates_json TEXT NOT NULL,config_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'needs_review',resolved_inbound_id TEXT REFERENCES catalog_inbounds(id),created_at TEXT NOT NULL,UNIQUE(instance_id,source_locator,tag,protocol));
CREATE TABLE inbound_client_keys(inbound_id TEXT NOT NULL REFERENCES catalog_inbounds(id),client_ref TEXT NOT NULL,legacy_id TEXT NOT NULL UNIQUE,PRIMARY KEY(inbound_id,client_ref));
INSERT OR IGNORE INTO inbound_client_keys SELECT i.id,c.core_client_ref,c.id FROM credential_material c JOIN catalog_inbounds i ON i.instance_id=c.instance_id AND i.tag=c.inbound_tag;
CREATE TABLE managed_user_state(id TEXT PRIMARY KEY,instance_id INTEGER NOT NULL REFERENCES instances(id),inbound_id TEXT NOT NULL REFERENCES catalog_inbounds(id),client_ref TEXT NOT NULL,ownership TEXT NOT NULL CHECK(ownership IN ('managed','adopted','external')),credential_ref TEXT REFERENCES credential_material(id),desired_json TEXT NOT NULL DEFAULT '{}',desired_enabled INTEGER NOT NULL DEFAULT 1,generation INTEGER NOT NULL DEFAULT 1,applied_generation INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending_apply',updated_at TEXT NOT NULL,UNIQUE(inbound_id,client_ref));
CREATE TABLE reconciliation_plans(id TEXT PRIMARY KEY,instance_id INTEGER NOT NULL REFERENCES instances(id),base_revision TEXT NOT NULL,managed_revision TEXT NOT NULL,summary_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned',mode TEXT NOT NULL DEFAULT 'observe',host_revision TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE reconciliation_actions(id INTEGER PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES reconciliation_plans(id),action TEXT NOT NULL,state TEXT NOT NULL,summary_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE reconciliation_instance_policy(instance_id INTEGER PRIMARY KEY REFERENCES instances(id),mode TEXT NOT NULL DEFAULT 'observe',deploy_mode TEXT NOT NULL DEFAULT 'external',revision INTEGER NOT NULL DEFAULT 1,restart_authorized INTEGER NOT NULL DEFAULT 0,base_path TEXT NOT NULL DEFAULT '');
CREATE TABLE inbound_merge_audit(id TEXT PRIMARY KEY,instance_id INTEGER NOT NULL REFERENCES instances(id),primary_id TEXT NOT NULL,secondary_id TEXT NOT NULL,backup_path TEXT NOT NULL,summary_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE legacy_node_redirects(legacy_id TEXT PRIMARY KEY REFERENCES nodes(id),canonical_id TEXT NOT NULL REFERENCES nodes(id),CHECK(legacy_id<>canonical_id));
CREATE TABLE inbound_retirements(inbound_id TEXT PRIMARY KEY REFERENCES catalog_inbounds(id),canonical_id TEXT REFERENCES catalog_inbounds(id),created_at TEXT NOT NULL);
